// Playwright MCP init script: replaces the browser microphone with a recorded teaching clip.
// The clip says a short binary-search explanation (about 11 s), then 5 s of silence, on loop,
// so voice features can be tested without a real microphone or relaxing browser security.
// Set window.__useRealMic = true before calling getUserMedia to use the real microphone instead.
(() => {
  const media = navigator.mediaDevices;
  if (!media || !media.getUserMedia) return;
  const realGetUserMedia = media.getUserMedia.bind(media);
  const SILENCE_SECONDS = 5;
  const CLIP_BASE64 = "";

  function clipBytes() {
    const binary = atob(CLIP_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes.buffer;
  }

  media.getUserMedia = async (constraints) => {
    if (!constraints || !constraints.audio || window.__useRealMic) return realGetUserMedia(constraints);
    const context = new AudioContext();
    await context.resume();
    const speech = await context.decodeAudioData(clipBytes());
    const padded = context.createBuffer(1, speech.length + speech.sampleRate * SILENCE_SECONDS, speech.sampleRate);
    padded.copyToChannel(speech.getChannelData(0), 0);
    const source = context.createBufferSource();
    source.buffer = padded;
    source.loop = true;
    const destination = context.createMediaStreamDestination();
    source.connect(destination);
    source.start();
    const stream = destination.stream;
    for (const track of stream.getAudioTracks()) {
      const stop = track.stop.bind(track);
      track.stop = () => {
        stop();
        try { source.stop(); } catch {}
        void context.close();
      };
    }
    if (constraints.video) {
      const video = await realGetUserMedia({ video: constraints.video });
      video.getVideoTracks().forEach((track) => stream.addTrack(track));
    }
    return stream;
  };
})();
